        bodyKo: "와일드 원 스켈레톤 티타늄은 NORQAIN 스켈레톤 무브먼트의 차세대 진화인 새로운 NORQAIN 4K 매뉴팩처 칼리버(NK26/1)로 구동됩니다. 산봉우리에서 영감을 받은 시그니처 브리지는 NORQAIN의 스위스 알파인 뿌리를 반영하며, 향상된 65시간 파워 리저브는 이전 와일드 원 Skeleton에 비해 하루의 자율성을 제공합니다. 400개 한정판으로 제작된 이 에디션은 사파이어 크리스탈 케이스백에 밝은 노란색으로 \"ONE OF 400\"이라는 문구가 눈에 띄게 표시되어 있습니다.",
