        bodyKo: "와일드 원 스켈레톤 X-Lite는 크기, 기능성 및 견고성 측면에서 시계의 가벼움 한계를 넘어 와일드 원 컨셉을 새로운 극한으로 끌어올리는 혁신적인 초경량 케이스 구조를 특징으로 합니다. 복잡하고 계층화된 아키텍처는 최대의 구조적 무결성을 위해 빌딩 블록처럼 조립된 30개 이상의 개별 구성 요소로 구성됩니다. 케이지는 검정색 NORTEQ®로 제작되었으며 매우 효율적인 충격 흡수 시스템을 통합합니다. 핵심에는 독점적인 X-Lite 케이싱 링이 NORTEQ®, 티타늄 및 알루미늄으로 제작된 케이스 내에 통합되어 있습니다. 추가 충격 흡수 장치가 구조 전체에 전략적으로 배치되어 시계가 슬림하고 착용 가능한 프로필을 유지하면서 5,000G 이상의 충격을 견딜 수 있도록 해줍니다.",
