        bodyKo: "아이스하키장의 거친 표면에서 영감을 받은 흰색 \"스크래치드 아이스\" 다이얼은 첫 대결부터 마지막 ​​순간까지 경기의 강렬함을 포착합니다. 맥박계가 포함된 흰색 내부 베젤에는 심장박동 표시기와 200 표시의 시간 초과 기호가 있습니다. 이 기호는 게임의 속도와 강도에 대한 순전히 그래픽적이고 기발한 참조 역할을 하며 숨을 쉬도록 상징적으로 상기시켜줍니다. 9시 방향에는 화이트 하키 페이스오프 원형 카운터가 교차된 하키 스틱으로 장식된 작은 세컨즈 디스크와 짝을 이루며 이는 스포츠의 정체성에 대한 경쾌한 찬사입니다. 12시와 6시 방향의 블랙 카운터(NHL 로고가 자랑스럽게 표시되어 있음)는 대담한 대비를 연출하며 요일 및 날짜 표시는 일상적인 기능을 보장합니다. 하키에서 영감을 받은 세련된 디테일이 함께 어우러져 정확성, 강렬함, 성능을 기념하는 독특한 시계를 만들어냅니다.",
