        bodyKo: "오픈 케이스백을 자세히 살펴보면 “Enjoy Life” 라는 인상적인 인그레이빙으로 강조된 독특한 아이스크림 에디션 디자인이 드러납니다. ”이 독점적인 디테일은 프리덤 60 Chrono의 시대를 초월한 우아함을 유지하면서 시계의 유쾌한 성격을 반영합니다.",
        image: "/products/nq-pdp/freedom-60-chrono-40mm-enjoy-life-special-edition/story-2.jpg",
